#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# STAGES — authored for the Chrome Web Store submission (first release, 0.1.0).
# 每一步对应仪表盘里的一个页面；能自动验证的都放在第 1 步，人只需要点与粘贴。
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# 干跑：WIZARD_DRY_RUN=1 时不打开浏览器、不等待人工确认（自测 / CI 用）。
if [[ "${WIZARD_DRY_RUN:-}" == "1" ]]; then
  open_url() { note "[dry-run] 本应打开 $1"; }
  pause() { note "[dry-run] 跳过人工确认"; }
fi

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REL="$ROOT/.spike/release"
ZIP=""
SHA=""
VERSION=""
PRIVACY_URL="https://dtdths.github.io/turbo-json-viewer/privacy/"

# listing <lang> [field] — 打印商店文案（单一来源 docs/release/listing.json）。
listing() { node "$ROOT/scripts/print-listing.mjs" "$@"; }

# _asset_dims <file> — 打印 PNG 宽高（读 IHDR，不依赖 sips / ImageMagick）。
_asset_dims() {
  node -e '
    const fs = require("node:fs");
    const b = fs.readFileSync(process.argv[1]);
    console.log(b.readUInt32BE(16) + "x" + b.readUInt32BE(20));
  ' "$1"
}

banner "Chrome Web Store 首次提交 — Turbo JSON Viewer"

# ──────────────────────────────────────────────────────────────────────
stage "预检（自动）：构建 → 打包 → 素材 → 文案"

step "构建（node build.mjs）"
node "$ROOT/build.mjs" >/dev/null
note "dist/ 已重建"

step "打包（node scripts/package.mjs）"
PKG_OUT="$(node "$ROOT/scripts/package.mjs")" || { warn "打包失败，先修构建"; exit 1; }
printf '%s\n' "$PKG_OUT" | sed 's/^/  /'
ZIP="$(printf '%s\n' "$PKG_OUT" | sed -n 's/^产物 //p')"
SHA="$(printf '%s\n' "$PKG_OUT" | sed -n 's/^sha256 //p')"
VERSION="$(node -e 'console.log(JSON.parse(require("node:fs").readFileSync(process.argv[1],"utf8")).version)' "$ROOT/dist/manifest.json")"
note "版本 $VERSION · 包 $(basename "$ZIP") · sha256 ${SHA:0:12}…"

step "校验 listing 文案（名称 ≤75 / 摘要 ≤132 字符）"
node "$ROOT/scripts/print-listing.mjs" --check | sed 's/^/  /'

step "校验商店素材（5 张 1280×800 截图 + 440×280 tile）"
ASSETS_OK=1
for i in 01-tree 02-search 03-expression 04-workspace 05-edit; do
  f="$ROOT/.spike/store/screens/shot-$i.png"
  if [[ ! -f "$f" ]]; then warn "缺截图 shot-$i.png（先跑 npm run assets）"; ASSETS_OK=0; continue; fi
  dims="$(_asset_dims "$f")"
  [[ "$dims" == "1280x800" ]] || { warn "shot-$i.png 尺寸 ${dims}，应为 1280x800"; ASSETS_OK=0; }
done
TILE="$ROOT/.spike/store/screens/promo-440x280.png"
if [[ -f "$TILE" ]]; then
  dims="$(_asset_dims "$TILE")"
  [[ "$dims" == "440x280" ]] || { warn "promo-440x280.png 尺寸 ${dims}，应为 440x280"; ASSETS_OK=0; }
else
  warn "缺 promo-440x280.png（先跑 npm run assets）"; ASSETS_OK=0
fi
(( ASSETS_OK )) && note "素材尺寸全部合规"

step "校验隐私政策页"
[[ -f "$ROOT/docs/privacy/index.html" ]] && note "$PRIVACY_URL ← docs/privacy/index.html" || warn "缺 docs/privacy/index.html"

if (( ! ASSETS_OK )); then
  warn "素材不全；仍可继续，但仪表盘会卡在必填项"
fi
pause "看完上面的预检结果，按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "开发者账号与一次性注册费"

step "打开 Chrome Web Store Developer Dashboard："
open_url "https://chrome.google.com/webstore/devconsole"
step "用要长期持有这个扩展的 Google 账号登录（换号很麻烦，先想清楚）。"
step "首次进入会要求支付一次性注册费并接受开发者协议。"
step "付款前把金额记下来——官方正文没写数额，社区共识 US\$5，但以付款页为准。"
warn "这一步只能你本人做：涉及付款与实名协议。"
ask CW_FEE "付款页显示的实际金额（例如 US\$5，记下来回填调研 §12-E）"
pause "账号可用、注册费已付？按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "创建 item 并上传 zip"

step "Dashboard → Items → New item。"
step "上传这个文件（直接复制路径）："
printf '  %s%s%s\n' "$BOLD" "$ZIP" "$RESET"
note "sha256 $SHA"
step "上传后确认页面没有报 manifest 错误；版本应显示 ${VERSION}。"
step "若提示版本未递增：改 src/app/manifest.json 的 version（见 docs/release/checklist.md §F），回到第 1 步重打包。"
pause "zip 已上传、无报错？按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "Store listing（默认语言：英文）"

step "打开左侧 Store listing 页，逐栏粘贴（下面是当前文案）："
listing en
step "Category 选 Developer Tools；Language 默认 English。"
step "Store icon 无需上传（随包的 128×128 会被读取）。"
step "Screenshots：按顺序上传下面 5 张（全出血、无留白），标题用括号里的说明："
for pair in \
  "01-tree:1" "02-search:2" "03-expression:3" "04-workspace:4" "05-edit:5"; do
  f="${pair%%:*}"; n="${pair##*:}"
  printf '  %s. %s\n' "$n" "$ROOT/.spike/store/screens/shot-$f.png"
done
step "Small promo tile：上传 $TILE"
step "截图说明文字（可选但建议填）："
listing en --field captions
pause "英文 listing 填完？按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "Store listing（新增语言：简体中文）"

step "Store listing → 语言下拉 → Add language → 选 Chinese (Simplified)。"
step "中文 listing 也要求截图；同一批图可直接复用（界面是英文，说明写中文）。"
listing zh
pause "中文 listing 填完？按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "Privacy practices（隐私问卷）"

step "打开左侧 Privacy practices，按下面口径填（本地处理也算处理用户数据，别选「不处理任何数据」）："
listing en --field singlePurpose
listing en --field permissions
listing en --field dataUsage
step "Privacy policy URL 填："
printf '  %s%s%s\n' "$BOLD" "$PRIVACY_URL" "$RESET"
note "页面在 docs/privacy/index.html；GitHub Pages 从 docs/ 发布（需先在仓库 Settings → Pages 选 Deploy from branch: master /docs）。"
step "Test instructions 填（含对 core.eval 方法名的说明，能少一轮审核往返）："
listing en --field testInstructions
pause "Privacy practices 填完、Privacy policy URL 已保存？按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "分发方式与提交审核"

step "Distribution / Visibility 选 Unlisted（链接可装、不进商店列表；审核流程与 Public 相同）。"
step "确认没有勾选任何「付费 / 需要登录」项（我们都没有）。"
step "点 Submit for review。"
step "记录提交时间；审核通常几天，超过 3 周无更新可联系支持。"
ask CW_SUBMITTED "提交日期（YYYY-MM-DD）"
pause "已提交？按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────
stage "发布后冒烟（安装真机版）"

step "审核通过后，用无痕窗口打开商店链接安装。"
step "核对权限提示：应只有「存储」与右键菜单相关项，与 listing 描述一致。"
step "粘贴一份 10 MB JSON：首帧正常、滚动跟手。"
step "普通网页选中 JSON → 右键 → Turbo JSON Viewer → 打开查看 / 下载 JSON。"
step "卸载扩展，确认本地设置随卸载清除。"
step "把这一轮的实测结论回填 docs/research/mv3-store.md §12-E（注册费、上传上限、视频是否必填等）。"

# 提交记录
mkdir -p "$REL"
LOG="$REL/submission-$VERSION.md"
{
  echo "# 提交记录 — Turbo JSON Viewer $VERSION"
  echo
  echo "- 日期：$(date '+%Y-%m-%d %H:%M %Z')"
  echo "- 分发：Unlisted"
  echo "- 包：\`$(basename "$ZIP")\`"
  echo "- sha256：\`$SHA\`"
  [[ -n "${CW_FEE:-}" ]] && echo "- 注册费（付款页实见）：$CW_FEE"
  [[ -n "${CW_SUBMITTED:-}" ]] && echo "- 提交日期：$CW_SUBMITTED"
  echo "- 素材：\`.spike/store/screens/\`（5×1280×800 + 440×280）"
  echo "- listing：\`docs/release/listing.json\`（en + zh）"
  echo "- 隐私政策：$PRIVACY_URL"
} > "$LOG"

finish
note "提交记录：$LOG"
note "下一步（审核通过后）：把 Distribution 切到 Public；有拒绝意见按 Status tab 整改重提。"
